SELECT 

WHERE true

AND q.kind = #{q.kind}
AND q.result = #{q.result}
AND q.company_id = #{q.companyId}
AND q.partner_id = #{q.partnerId}
AND q.prd_order_id = #{q.prdOrderId}
AND q.inspect_date >= #{q.dateFrom}
AND q.inspect_date <= #{q.dateTo}

    AND (q.no ILIKE #{kw} OR d.no ILIKE #{kw} OR r.no ILIKE #{kw} OR o.no ILIKE #{kw} OR q.target_desc ILIKE #{kw}
         OR p.code ILIKE #{kw} OR p.name LIKE #{kw} OR p.short_name LIKE #{kw})

ORDER BY q.inspect_date DESC, q.id DESC

